281		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"},
282		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
283		  {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
284		  {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003}
285		]}`))
286		if err != nil {
287			t.Fatalf("parse: %v", err)
288		}
289		rep, err := l.ReconcileFlow(entries)
290		if err != nil {
291			t.Fatalf("reconcile: %v", err)
292		}
