294		wantOrder := []struct {
295			id     string
296			kind   string
297			status string
298		}{
299			{"r1", "refund", ReconFieldMismatch},
300			{"p1", "payment", ReconMatched},
301			{"r2", "refund", ReconFieldMismatch},
302			{"p2", "payment", ReconMatched},
303		}
304		if len(rep.Results) != len(wantOrder) {
