333		rec1 := rep.Results[0].Record
334		if rec1 == nil || rec1.Kind != "refund" || rec1.ID != "r1" || rec1.Seq != 1 ||
335			rec1.SettlementID != "p1" || rec1.Amount != 1000 || rec1.Fee != 3 || rec1.Charged != 1003 {
336			t.Fatalf("r1 record must carry true origin payment p1: %+v", rec1)
337		}
338		rec2 := rep.Results[2].Record
339		if rec2 == nil || rec2.Kind != "refund" || rec2.ID != "r2" || rec2.Seq != 2 ||
340			rec2.SettlementID != "p2" {
341			t.Fatalf("r2 record must carry true origin payment p2: %+v", rec2)
342		}
343		// 匹配的付款仍带各自退款关联，不因退款串号而丢失。
344		if rep.Results[1].Record == nil || rep.Results[1].Record.RefundID != "r1" {
345			t.Fatalf("p1 must still link refund r1: %+v", rep.Results[1].Record)
346		}
347		if rep.Results[3].Record == nil || rep.Results[3].Record.RefundID != "r2" {
348			t.Fatalf("p2 must still link refund r2: %+v", rep.Results[3].Record)
349		}
350	
351		// 四条记录全部通过各自编号找到：缺失列表（付款与退款）必须为空。
352		if len(rep.MissingRefunds) != 0 {
353			t.Fatalf("matched-by-id refunds must not be missing: %+v", rep.MissingRefunds)
354		}
355		if len(rep.MissingPayments) != 0 {
356			t.Fatalf("covered payments must not be missing: %+v", rep.MissingPayments)
357		}
358	
359		// 两侧扣款合计 2006、退款合计 2006、净扣款为零、净差额为十进制零。
360		regAssertBalancedTotals(t, rep, "2006", "2006")
361	
362		// 交换回正确的原付款编号后四条全部恢复 matched；金额字段本就一致。
363		corrected := []FlowEntry{
364			{Index: 0, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
365				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
366			{Index: 1, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
367			{Index: 2, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
368				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
369			{Index: 3, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
370		}
371		rep2, err := l.ReconcileFlow(corrected)
372		if err != nil {
373			t.Fatalf("reconcile corrected: %v", err)
374		}
375		for i, r := range rep2.Results {
376			if r.Status != ReconMatched || len(r.Diffs) != 0 {
377				t.Fatalf("corrected result %d (%s)=%+v want matched", i, r.ID, r)
378			}
379		}
380		if len(rep2.MissingPayments) != 0 || len(rep2.MissingRefunds) != 0 {
381			t.Fatalf("corrected missing=%+v/%+v", rep2.MissingPayments, rep2.MissingRefunds)
382		}
383		regAssertBalancedTotals(t, rep2, "2006", "2006")
384	}
385	
386	// TestReconcileRefundedPaymentStillCheckedOnItsOwn 付款曾经退款不影响原付款的
387	// 核对：同一批流水里一笔退款 settlement_id 串号，另一笔原付款按自己的编号与
388	// 金额判断；两类记录各按自己的编号空间匹配，不能因为金额相同就互相替代。
389	func TestReconcileRefundedPaymentStillCheckedOnItsOwn(t *testing.T) {
390		l, _ := regNetZeroLedger(t)
391		// r1 编号命中、金额正确，但原付款误填成 p2 -> field_mismatch(settlement_id)；
392		// p1 按原扣款如实呈现 -> matched。两笔金额相同（1003）不允许互相顶替。
393		entries := []FlowEntry{
394			{Index: 0, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
395				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
396			{Index: 1, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc",
397				Amount: 1000, Fee: 3, Charged: 1003},
398		}
399		rep, err := l.ReconcileFlow(entries)
400		if err != nil {
401			t.Fatalf("reconcile: %v", err)
402		}
403		if rep.Results[0].Status != ReconFieldMismatch {
404			t.Fatalf("r1=%s want field_mismatch", rep.Results[0].Status)
405		}
406		if d := regDiffMap(rep.Results[0]); len(d) != 1 || d["settlement_id"] != [2]string{"p1", "p2"} {
407			t.Fatalf("r1 diffs=%v", d)
408		}
409		if rep.Results[1].Status != ReconMatched {
410			t.Fatalf("p1=%s want matched even though it was refunded and r1 mismatches", rep.Results[1].Status)
411		}
412		// 已退款的付款匹配时仍带退款关联；退款记录带真正的原付款编号。
413		if rep.Results[1].Record == nil || rep.Results[1].Record.RefundID != "r1" {
414			t.Fatalf("p1 must still link refund r1: %+v", rep.Results[1].Record)
415		}
416		if rep.Results[0].Record == nil || rep.Results[0].Record.SettlementID != "p1" {
417			t.Fatalf("r1 record must carry true settlement p1: %+v", rep.Results[0].Record)
418		}
419		// p1、r1 均已覆盖；缺失只剩 p2、r2。
420		if ids := refs(rep.MissingPayments); ids != "p2" {
421			t.Fatalf("missing payments=%s want p2", ids)
422		}
423		if ids := refs(rep.MissingRefunds); ids != "r2" {
424			t.Fatalf("missing refunds=%s want r2", ids)
425		}
426	}
427	
428	// TestReconcileNetZeroDeviationsAndRecoveryAcrossSameBatch 同一批流水先呈现
429	// 跨记录偏差（净额对平），再把偏差全部改回账本原值：偏差状态、缺失列表、
430	// 汇总金额与恢复后的 matched 必须在同一份公开报告结构里自洽表达同一批流水。
431	func TestReconcileNetZeroDeviationsAndRecoveryAcrossSameBatch(t *testing.T) {
432		l, _ := regNetZeroLedger(t)
433	
434		// 混合一批：p1 多记 20、p2 少记 20（付款净额对平）；r1 串号到 p2
435		// （退款净额因 r2 缺席不再对平，但 r1 自身仍是 settlement_id 不符）。
436		bad := []FlowEntry{
437			{Index: 0, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 980, Fee: 3, Charged: 983},
438			{Index: 1, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
439				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
440			{Index: 2, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1020, Fee: 3, Charged: 1023},
441		}
442		rep, err := l.ReconcileFlow(bad)
443		if err != nil {
444			t.Fatalf("reconcile: %v", err)
445		}
446		wantStatus := []string{ReconFieldMismatch, ReconFieldMismatch, ReconFieldMismatch}
447		for i, r := range rep.Results {
448			if r.Status != wantStatus[i] {
449				t.Fatalf("bad batch result %d (%s)=%s want %s", i, r.ID, r.Status, wantStatus[i])
450			}
451		}
452		// 输入顺序同时保留（付款与退款交错，不重排）。
453		wantOrder := []string{"p2", "r1", "p1"}
454		for i, r := range rep.Results {
455			if r.ID != wantOrder[i] || r.Index != i {
456				t.Fatalf("result %d id=%s index=%d want %s", i, r.ID, r.Index, wantOrder[i])
457			}
458		}
459		if len(rep.MissingPayments) != 0 {
460			t.Fatalf("bad batch missing payments=%+v", rep.MissingPayments)
461		}
462		if ids := refs(rep.MissingRefunds); ids != "r2" {
463			t.Fatalf("bad batch missing refunds=%s want r2", ids)
464		}
465		// 付款扣款合计仍为 2006（983+1023），但流水只来一笔退款 1003：
466		// 净扣款 = 1003，而账本净扣款为 0，净差额 +1003——逐项偏差与汇总并存。
467		fl := regRow(t, rep.Totals.Flow, "aa-1", "usdc")
468		if fl.ChargedTotal != "2006" || fl.RefundedTotal != "1003" || fl.NetCharged != "1003" {
469			t.Fatalf("flow totals=%+v", fl)
470		}
471		if d := regDiff(t, rep, "aa-1", "usdc"); d.NetChargedDiff != "1003" {
472			t.Fatalf("net diff=%+v want 1003", d)
473		}
474	
475		// 全部偏差改回账本原值（r1 指回 p1），并补齐 r2 与正确的 p1/p2：
476		// 四条全部 matched，两侧合计 2006/2006、净差额恢复为零。
477		good := []FlowEntry{
478			{Index: 0, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
479			{Index: 1, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
480				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
481			{Index: 2, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1000, Fee: 3, Charged: 1003},
482			{Index: 3, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
483				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
484		}
485		rep2, err := l.ReconcileFlow(good)
486		if err != nil {
487			t.Fatalf("reconcile good: %v", err)
488		}
489		for i, r := range rep2.Results {
490			if r.Status != ReconMatched {
491				t.Fatalf("good batch result %d (%s)=%s want matched", i, r.ID, r.Status)
492			}
493		}
494		if len(rep2.MissingPayments) != 0 || len(rep2.MissingRefunds) != 0 {
495			t.Fatalf("good batch missing=%+v/%+v", rep2.MissingPayments, rep2.MissingRefunds)
496		}
497		regAssertBalancedTotals(t, rep2, "2006", "2006")
498	}
499	
500	// TestReconcileNetZeroDeviationsAreValidReportsNotErrors 这些场景的输入字段与
501	// 数值全部合法：跨记录偏差必须作为正常对账报告返回（退出语义层面无错误），
502	// 不能变成 invalid_parameter，也不能省略不一致的逐条结果。
503	func TestReconcileNetZeroDeviationsAreValidReportsNotErrors(t *testing.T) {
504		l, _ := regNetZeroLedger(t)
505	
506		cases := []struct {
507			name    string
508			raw     string
509			badID   string // 必然带字段差异的编号
510			diffFld string
511		}{
512			{
513				"offsetting payment amounts",
514				`{"entries":[
515				 {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1020,"fee":3,"charged":1023},
516				 {"kind":"payment","id":"p2","account":"aa-1","asset":"usdc","amount":980,"fee":3,"charged":983}
517				]}`,
518				"p1", "amount",
519			},
520			{
521				"swapped refund settlements",
522				`{"entries":[
523				 {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p2"},
524				 {"kind":"refund","id":"r2","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"}
525				]}`,
526				"r1", "settlement_id",
527			},
528			{
529				"amount/fee breakdown shift with equal charged",
530				`{"entries":[
531				 {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":990,"fee":13,"charged":1003}
532				]}`,
533				"p1", "amount",
534			},
535		}
536		for _, c := range cases {
537			entries, err := ParseReconcileRequest([]byte(c.raw))
538			if err != nil {
539				t.Fatalf("%s: valid input must parse: %v", c.name, err)
540			}
541			rep, err := l.ReconcileFlow(entries)
542			if err != nil || rep == nil {
543				t.Fatalf("%s: deviations are a normal report, not invalid_parameter: rep=%+v err=%v", c.name, rep, err)
544			}
545			found := false
546			for _, r := range rep.Results {
547				if r.ID != c.badID {
548					continue
549				}
550				found = true
551				if r.Status != ReconFieldMismatch {
552					t.Fatalf("%s: %s status=%s want field_mismatch", c.name, r.ID, r.Status)
553				}
554				if _, ok := regDiffMap(r)[c.diffFld]; !ok {
555					t.Fatalf("%s: %s missing diff on %s: %+v", c.name, r.ID, c.diffFld, r.Diffs)
556				}
557			}
558			if !found {
559				t.Fatalf("%s: inconsistent result for %s must not be omitted: %+v", c.name, c.badID, rep.Results)
560			}
561		}
562	}
563	
564	// TestReconcileNetZeroDeviationsAreReadOnly 带跨记录偏差的对账前后，余额、
565	// 付款与退款历史以及账本文件内容必须逐字节保持一致（偏差只存在于报告中）。
566	func TestReconcileNetZeroDeviationsAreReadOnly(t *testing.T) {
567		l, path := regNetZeroLedger(t)
568	
569		before, err := l.Query()
570		if err != nil {
571			t.Fatalf("query before: %v", err)
572		}
573		bj, err := json.Marshal(before)
574		if err != nil {
575			t.Fatalf("marshal before: %v", err)
576		}
577		diskBefore, err := os.ReadFile(path)
578		if err != nil {
579			t.Fatalf("read ledger before: %v", err)
580		}
581	
582		deviating := []FlowEntry{
583			{Index: 0, Kind: "payment", ID: "p1", Account: "aa-1", Asset: "usdc", Amount: 1020, Fee: 3, Charged: 1023},
584			{Index: 1, Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc", Amount: 980, Fee: 3, Charged: 983},
585			{Index: 2, Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
586				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p2"},
587			{Index: 3, Kind: "refund", ID: "r2", Account: "aa-1", Asset: "usdc",
588				Amount: 1000, Fee: 3, Charged: 1003, SettlementID: "p1"},
589		}
590		rep, err := l.ReconcileFlow(deviating)
591		if err != nil {
592			t.Fatalf("reconcile: %v", err)
593		}
594		for i, r := range rep.Results {
595			if r.Status != ReconFieldMismatch {
596				t.Fatalf("setup: result %d (%s)=%s want field_mismatch", i, r.ID, r.Status)
597			}
598		}
599	
600		after, err := l.Query()
601		if err != nil {
602			t.Fatalf("query after: %v", err)
603		}
604		aj, err := json.Marshal(after)
605		if err != nil {
606			t.Fatalf("marshal after: %v", err)
607		}
608		if !reflect.DeepEqual(before, after) {
609			t.Fatalf("ledger state changed by reconcile:\nbefore=%s\nafter =%s", bj, aj)
610		}
611		diskAfter, err := os.ReadFile(path)
612		if err != nil {
613			t.Fatalf("read ledger after: %v", err)
614		}
615		if string(diskBefore) != string(diskAfter) {
616			t.Fatalf("ledger file changed by reconcile:\nbefore=%s\nafter =%s", diskBefore, diskAfter)
617		}
618	
619		// 重新打开同一文件，余额与成功历史仍与对账前完全一致。
620		l2, err := Open(path)
621		if err != nil {
622			t.Fatalf("reopen: %v", err)
623		}
624		defer l2.Close()
625		reopened, err := l2.Query()
626		if err != nil {
627			t.Fatalf("query reopened: %v", err)
628		}
629		if !reflect.DeepEqual(before, reopened) {
630			rj, _ := json.Marshal(reopened)
631			t.Fatalf("reopened ledger differs:\ndisk=%s\nmem =%s", rj, bj)
632		}
633	}
