127		go func() {
128			defer wg.Done()
129			submitRes, submitErr = lSubmit.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
130				intent("p1", acct, asset, 500),
131				intent("p2", acct, asset, 300),
132			}})
133		}()
134	
135		// 等 A 把 p1 完整落账、停在 p2 的保存点（批次仍在保存、锁仍被持有）。
136		<-gate.reached
137	
138		// 句柄 B：就在该付款批次仍在保存时发起范围对账。它应当在同一把账本锁上
139		// 排队，直到 A 整批处理完毕，而不是基于“p1 已成功、p2 未定”的中途状态
140		// 提前返回仅含前项成功的报告。
141		wg.Add(1)
142		go func() {
143			defer wg.Done()
144			defer close(reconDone)
145			close(reconStarted)
146			reconRes, reconErr = lRecon.ReconcileFlowRanged(entries, bounds)
147		}()
148	
149		<-reconStarted
150		// 让出 P，令对账 goroutine 实际运行到争夺账本锁并排队；A 仍停在 p2 保存点。
151		for i := 0; i < 4; i++ {
152			runtime.Gosched()
153		}
154		// 付款批次仍在保存、锁仍被 A 持有：对账绝不可能在此刻返回。正确实现下对账
155		// 线程正阻塞在同一把账本锁上，因此该非阻塞检查不会误报；它直接锁定“对账
156		// 等待在途付款批次整批完成”这一性质（仅凭结果无法区分等待与否——中途状态
157		// 与失败结局的报告可能恰好一致，本检查补上这重保障）。
158		select {
159		case <-reconDone:
160			t.Fatal("ranged reconcile returned while the payment batch was still saving; it must wait for the whole batch")
161		default:
162		}
163		close(gate.release) // 放行 p2 保存（成功或失败），随后整批结束并释放锁
164		wg.Wait()
165	
166		SetFailHook(lSubmit, nil) // 用例结束，拆卸故障注入
167	
168		if submitErr != nil {
169			t.Fatalf("submit batch: %v", submitErr)
170		}
171		if reconErr != nil {
172			t.Fatalf("ranged reconcile: %v", reconErr)
173		}
174	
175		// ---- 付款批次逐项结果：与输入顺序一一对应，各自独立处理 ----
176		if got := statuses(submitRes); !reflect.DeepEqual(got, wantSubmitStatuses) {
177			t.Fatalf("submit statuses=%v want %v", got, wantSubmitStatuses)
178		}
179		if submitRes.Results[0].ID != "p1" || submitRes.Results[1].ID != "p2" {
180			t.Fatalf("submit results out of order: %+v", submitRes.Results)
181		}
182		assertRecord(t, "p1 submit record", submitRes.Results[0].Record, wantP1)
183		if failSecond {
184			// p2 保存失败：报告 storage_error、无成功记录，前项 p1 保留不回滚。
185			if r := submitRes.Results[1]; r.Status != StatusStorage || r.Record != nil {
186				t.Fatalf("failed p2: %+v", r)
187			}
188		} else {
189			assertRecord(t, "p2 submit record", submitRes.Results[1].Record, wantP2)
190		}
191	
192		// ---- 对账报告：整份基于付款批次结束后的同一个完整账本状态 ----
193		rep := reconRes
194		if len(rep.Results) != 2 {
195			t.Fatalf("report results=%d want 2: %+v", len(rep.Results), rep.Results)
196		}
197		for i, wantID := range []string{"p1", "p2"} {
198			r := rep.Results[i]
199			if r.Index != i || r.ID != wantID || r.Kind != "payment" {
200				t.Fatalf("result %d out of order: %+v", i, r)
201			}
202			if r.Status != wantStatuses[i] {
203				t.Fatalf("result %d (%s) status=%s want %s", i, r.ID, r.Status, wantStatuses[i])
204			}
205			if len(r.Diffs) != 0 {
206				t.Fatalf("result %d (%s) unexpected diffs: %+v", i, r.ID, r.Diffs)
207			}
208		}
209		// p1 两种结局下都是范围外（seq=1 不满足 after=1 < seq），携带原记录、
210		// 不比较字段；p2 成功时为 matched 并携带记录。
211		assertRefUntouched(t, *rep.Results[0].Record, wantP1Ref, "p1 out_of_scope record")
212		if failSecond {
213			// 失败的 p2 不能被算成成功记录：missing_in_ledger 且不携带成功记录。
214			if rep.Results[1].Record != nil {
215				t.Fatalf("failed p2 must not carry a ledger record: %+v", rep.Results[1].Record)
216			}
217		} else {
218			assertRefUntouched(t, *rep.Results[1].Record, wantP2Ref, "p2 matched record")
219		}
220	
221		// 两种结局下付款与退款缺失列表都为空：成功时范围内只有 p2 且已被流水
222		// 覆盖；失败时付款范围为空，根本没有入选记录；退款历史恒为空。
223		if len(rep.MissingPayments) != 0 {
224			t.Fatalf("missing payments=%+v want empty", rep.MissingPayments)
225		}
226		if len(rep.MissingRefunds) != 0 {
227			t.Fatalf("missing refunds=%+v want empty", rep.MissingRefunds)
228		}
229	
230		// 最大成功序号与本次实际采用的四个边界：上界缺省，必须取批次结束后完整
231		// 历史的最大付款序号（2 或仅成功项的 1），不能提前返回停在前项的半批值；
232		// 退款没有历史，最大序号与上下界均为零（范围为空）。
233		if rep.MaxPaymentSeq != wantMaxPaySeq || rep.MaxRefundSeq != 0 {
234			t.Fatalf("max seqs=%d/%d want %d/0", rep.MaxPaymentSeq, rep.MaxRefundSeq, wantMaxPaySeq)
235		}
236		if rep.PaymentAfter != 1 || rep.PaymentThrough != wantPayThrough ||
237			rep.RefundAfter != 0 || rep.RefundThrough != 0 {
238			t.Fatalf("bounds payment=%d,%d refund=%d,%d want payment=1,%d refund=0,0",
239				rep.PaymentAfter, rep.PaymentThrough, rep.RefundAfter, rep.RefundThrough, wantPayThrough)
240		}
241	
242		// 金额汇总（十进制字符串）：
243		// 成功——账本侧只计入选的 p2（300），流水侧排除范围外 p1 后也只计 p2
244		// （300），净扣款差额为零，p1 的 501 不混入任一侧；
245		// 失败——账本侧无入选付款（无汇总行），流水侧仍逐条计入账本外 p2 的 300，
246		// 净差额按流水减账本为 300。
247		if len(rep.Totals.Ledger) != wantLedgerRowCount {
248			t.Fatalf("ledger totals rows=%d want %d: %+v", len(rep.Totals.Ledger), wantLedgerRowCount, rep.Totals.Ledger)
249		}
250		if !failSecond {
251			if got := findTotalRow(t, rep.Totals.Ledger, acct, asset); got != wantLedgerRow {
252				t.Fatalf("ledger totals:\n got %+v\nwant %+v", got, wantLedgerRow)
253			}
254		}
255		if got := findTotalRow(t, rep.Totals.Flow, acct, asset); got != wantFlowRow {
256			t.Fatalf("flow totals:\n got %+v\nwant %+v", got, wantFlowRow)
257		}
258		if len(rep.Totals.Flow) != 1 {
259			t.Fatalf("flow totals rows=%d want 1: %+v", len(rep.Totals.Flow), rep.Totals.Flow)
260		}
261		if len(rep.NetDiff) != 1 {
262			t.Fatalf("net diff rows=%d want 1: %+v", len(rep.NetDiff), rep.NetDiff)
263		}
264		if rep.NetDiff[0] != wantNetDiff {
265			t.Fatalf("net diff:\n got %+v\nwant %+v", rep.NetDiff[0], wantNetDiff)
266		}
267	
268		// ---- 对账只读：不新增付款或退款，不改变批次完成后的余额与账本文件 ----
269		snap := mustQuery(t, lRecon)
270		if !reflect.DeepEqual(snap.Settlements, wantSettlements) {
271			t.Fatalf("settlements after reconcile:\n got %+v\nwant %+v (reconcile must not add payments)", snap.Settlements, wantSettlements)
272		}
273		if len(snap.Refunds) != 0 {
274			t.Fatalf("refunds after reconcile=%+v want empty", snap.Refunds)
275		}
276		if bal, _ := lRecon.Balance(acct, asset); bal != wantBalance {
277			t.Fatalf("balance after reconcile=%d want %d (reconcile must not move balances)", bal, wantBalance)
278		}
279	
280		// 账本文件不被对账改写：再对账一次，文件字节与报告都保持不变。
281		before, err := os.ReadFile(path)
282		if err != nil {
283			t.Fatal(err)
284		}
285		again, err := lRecon.ReconcileFlowRanged(entries, bounds)
286		if err != nil {
287			t.Fatalf("re-reconcile: %v", err)
288		}
289		if !reflect.DeepEqual(again, rep) {
290			t.Fatalf("re-reconcile not deterministic:\n first %+v\nagain %+v", rep, again)
291		}
292		after, err := os.ReadFile(path)
293		if err != nil {
294			t.Fatal(err)
295		}
296		if !bytes.Equal(before, after) {
297			t.Fatalf("ledger file rewritten by reconcile:\nbefore=%s\nafter =%s", before, after)
298		}
299	}
300	
301	// TestRangedReconcileWaitsForInFlightPaymentBatchBothSettled：p1、p2 都保存
302	// 成功（余额 199）。在批次中途发起的范围对账（payment_after=1、上界缺省）
303	// 必须等整批结束：最大付款序号与本次上界均为 2，下界仍为 1；p1 返回
304	// out_of_scope 并携带原记录，p2 返回 matched；两侧扣款合计都只计 p2 的
305	// 300，净扣款差额为零，p1 的 501 不混入本次范围；付款与退款缺失列表均空。
306	func TestRangedReconcileWaitsForInFlightPaymentBatchBothSettled(t *testing.T) {
307		runRangedReconcileDuringPaymentInterleave(t, false)
308	}
309	
310	// TestRangedReconcileWaitsForInFlightPaymentBatchSecondSaveFails：p1 成功、
311	// p2 保存失败。付款批次保留 p1、p2 报 storage_error、余额 499；并发范围对账
312	// 仍正常返回：最大付款序号与本次上界均为 1，付款范围 (1,1] 为空；p1 仍是
313	// out_of_scope，p2 为 missing_in_ledger 且不携带成功记录；账本侧没有入选
314	// 付款，流水侧仍计入账本外 p2 的 300，净扣款差额按流水减账本为 300。
315	func TestRangedReconcileWaitsForInFlightPaymentBatchSecondSaveFails(t *testing.T) {
316		runRangedReconcileDuringPaymentInterleave(t, true)
317	}
318

