	}
	if len(rep.Totals.Ledger) != 0 {
		t.Fatalf("empty range ledger totals=%+v", rep.Totals.Ledger)
	}
}

func TestReconcileFlowRangedEmptyHistory(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1}})
	l := openOrFail(t, path)
