func TestReconcileFlowRangedDuplicatesCounted(t *testing.T) {
	l := rangeLedger(t)
	pa, pt := int64(1), int64(2)
	// p2 两次（都在范围内）-> duplicate，两条都计入流水侧。
	entries := []FlowEntry{
		flowEntry(0, "payment", "p2", "aa-1", "usdc", 2000, 6, 2006, ""),
		flowEntry(1, "payment", "p2", "aa-1", "usdc", 2000, 6, 2006, ""),
