			t.Fatalf("%s on corrupt: code=%d out=%s err=%s", cmd, r.code, r.out, r.err)
		}
	}

	// 非法 JSON 输入分类为 invalid_parameter（与磁盘损坏区分）。
	good := dir + "/good.json"
