		`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":99999999999999999999999}]}`,
	}
	for i, body := range bad {
		r := runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body)
