func TestCLISubmitDryRun(t *testing.T) {
	ledgerPath := t.TempDir() + "/ledger.json"
	if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
		`{"balances":[{"account":"aa-1","asset":"usdc","balance":100}]}`); r.code != 0 {
		t.Fatalf("init: %s", r.err)
	}

	// 规格示例：余额 100、费率 0，依次 70 与 40 —— 首项成功、次项余额不足。
	batch := `{"fee_bps":0,"intents":[
	  {"id":"p1","account":"aa-1","asset":"usdc","amount":70},
	  {"id":"p2","account":"aa-1","asset":"usdc","amount":40}
	]}`
	r := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, batch)
	if r.code != 0 {
		t.Fatalf("dry-run code=%d err=%s", r.code, r.err)
	}
	var res struct {
		DryRun  bool `json:"dry_run"`
		Results []struct {
			ID     string `json:"id"`
			Status string `json:"status"`
			Record *struct {
				Seq     int64 `json:"seq"`
				Charged int64 `json:"charged"`
			} `json:"record"`
		} `json:"results"`
	}
	if err := json.Unmarshal([]byte(r.out), &res); err != nil {
		t.Fatalf("decode: %v\n%s", err, r.out)
	}
	if !res.DryRun {
		t.Fatalf("dry-run output must carry dry_run=true: %s", r.out)
	}
	want := []string{"settled", "insufficient_balance"}
	if len(res.Results) != len(want) {
		t.Fatalf("got %d results", len(res.Results))
	}
	for i, x := range res.Results {
		if x.Status != want[i] {
			t.Fatalf("item %d=%s want %s", i, x.Status, want[i])
		}
	}
	if res.Results[0].Record == nil || res.Results[0].Record.Seq != 1 || res.Results[0].Record.Charged != 70 {
		t.Fatalf("predicted record: %+v", res.Results[0].Record)
	}
	if res.Results[1].Record != nil {
		t.Fatalf("failed item must not carry a record")
	}
	firstOut := r.out // query 会复用 r，先保存首次预览输出

	// 预览不写账本：余额仍为 100，没有任何结算记录，文件未变。
	r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
	var snap struct {
		Balances    []struct{ Balance int64 } `json:"balances"`
		Settlements []any                     `json:"settlements"`
	}
	if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
		t.Fatal(err)
	}
	if len(snap.Balances) != 1 || snap.Balances[0].Balance != 100 || len(snap.Settlements) != 0 {
		t.Fatalf("ledger changed by dry-run: %+v", snap)
	}

	// 再次预览结果一致（确定性）。
	r2 := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, batch)
	if r2.out != firstOut {
		t.Fatalf("repeated dry-run differs:\n%s\n%s", firstOut, r2.out)
	}

	// 随后真实提交仍按首次提交处理：p1 成功（非 duplicate），余额变 30。
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, batch)
	if r.code != 0 {
		t.Fatalf("real submit: %s", r.err)
	}
	if strings.Contains(r.out, "dry_run") {
		t.Fatalf("real submit must not carry dry_run marker: %s", r.out)
	}
	var sub struct {
		Results []struct {
			ID     string `json:"id"`
			Status string `json:"status"`
		} `json:"results"`
	}
	if err := json.Unmarshal([]byte(r.out), &sub); err != nil {
		t.Fatal(err)
	}
	if sub.Results[0].Status != "settled" || sub.Results[1].Status != "insufficient_balance" {
		t.Fatalf("real submit must be first-time: %+v", sub.Results)
	}
	r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
	if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
		t.Fatal(err)
	}
	if snap.Balances[0].Balance != 30 || len(snap.Settlements) != 1 {
		t.Fatalf("after real submit: %+v", snap)
	}
}

func TestCLISubmitDryRunEdgeCases(t *testing.T) {
	ledgerPath := t.TempDir() + "/ledger.json"
	if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
		`{"balances":[{"account":"aa-1","asset":"usdc","balance":1000}]}`); r.code != 0 {
		t.Fatalf("init: %s", r.err)
	}

	// 合法空批次：带预览标记的空结果列表。
	if r := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, `{"fee_bps":0,"intents":[]}`); r.code != 0 ||
		strings.TrimSpace(r.out) != "{\n  \"dry_run\": true,\n  \"results\": []\n}" {
		t.Fatalf("empty dry-run: code=%d out=%q err=%s", r.code, r.out, r.err)
	}

	// 批次级错误：非法 JSON / 非法费率 / 非法限额 —— 退出码 1，无部分结果。
	bad := []string{
		`{not json`,
		`{"fee_bps":-1,"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc","max_charged":-1}],"intents":[]}`,
	}
	for i, body := range bad {
		r := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"}, body)
		if r.code != 1 || r.out != "" {
			t.Fatalf("case %d: code=%d out=%q (want 1, no partial output)", i, r.code, r.out)
		}
		if env := decodeOut(t, r.err); env["error"].(map[string]any)["kind"] != "invalid_parameter" {
			t.Fatalf("case %d envelope=%s", i, r.err)
		}
	}

	// 逐项业务失败仍是正常结果，退出码 0。
	r := runCLIWith(t, []string{"submit", "-l", ledgerPath, "--dry-run"},
		`{"fee_bps":0,"intents":[
		  {"id":"bad","account":"aa-1","asset":"usdc","amount":2000},
		  {"id":"","account":"aa-1","asset":"usdc","amount":1}
		]}`)
	if r.code != 0 {
		t.Fatalf("per-item failures must exit 0: %s", r.err)
	}
	var res struct {
		DryRun  bool                      `json:"dry_run"`
		Results []struct{ Status string } `json:"results"`
	}
	if err := json.Unmarshal([]byte(r.out), &res); err != nil {
		t.Fatal(err)
	}
	if !res.DryRun || len(res.Results) != 2 ||
		res.Results[0].Status != "insufficient_balance" || res.Results[1].Status != "invalid_parameter" {
		t.Fatalf("per-item dry-run results: %s", r.out)
	}

	// -f 输入文件与 --dry-run 可组合使用。
	inputPath := t.TempDir() + "/batch.json"
	if err := os.WriteFile(inputPath, []byte(
		`{"fee_bps":0,"intents":[{"id":"f1","account":"aa-1","asset":"usdc","amount":50}]}`), 0o600); err != nil {
		t.Fatal(err)
	}
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath, "-f", inputPath, "--dry-run"}, "")
	if r.code != 0 || !strings.Contains(r.out, `"dry_run": true`) || !strings.Contains(r.out, `"settled"`) {
		t.Fatalf("dry-run -f: code=%d out=%s err=%s", r.code, r.out, r.err)
	}

	// 未初始化 / 损坏账本沿用现有错误分类，且不创建账本。
	missing := t.TempDir() + "/nope.json"
	if r = runCLIWith(t, []string{"submit", "-l", missing, "--dry-run"}, `{"fee_bps":0,"intents":[]}`); r.code != 1 ||
		decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "ledger_not_initialized" {
		t.Fatalf("missing ledger dry-run: %+v", r)
	}
	corrupt := t.TempDir() + "/corrupt.json"
	if err := os.WriteFile(corrupt, []byte(`{"version":1,`), 0o600); err != nil {
		t.Fatal(err)
	}
	if r = runCLIWith(t, []string{"submit", "-l", corrupt, "--dry-run"}, `{"fee_bps":0,"intents":[]}`); r.code != 1 ||
		decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "corrupt_ledger" {
		t.Fatalf("corrupt ledger dry-run: %+v", r)
	}
}

func TestCLISubmitChargeLimits(t *testing.T) {
	ledgerPath := t.TempDir() + "/ledger.json"
	r := runCLIWith(t, []string{"init", "-l", ledgerPath},
		`{"balances":[{"account":"aa-1","asset":"usdc","balance":2000},{"account":"aa-1","asset":"eth","balance":100}]}`)
	if r.code != 0 {
		t.Fatalf("init code=%d err=%s", r.code, r.err)
	}

	// 限额内、恰好到顶、超限、未列出组合逐项对应，退出码 0。
	batch := `{"fee_bps":0,
	  "limits":[{"account":"aa-1","asset":"usdc","max_charged":1000}],
	  "intents":[
	    {"id":"p1","account":"aa-1","asset":"usdc","amount":600},
	    {"id":"p2","account":"aa-1","asset":"usdc","amount":400},
	    {"id":"p3","account":"aa-1","asset":"usdc","amount":1},
	    {"id":"p4","account":"aa-1","asset":"eth","amount":50}
	  ]}`
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, batch)
	if r.code != 0 {
		t.Fatalf("submit code=%d err=%s", r.code, r.err)
	}
	var res struct {
		Results []struct {
			ID     string `json:"id"`
			Status string `json:"status"`
			Reason string `json:"reason"`
		} `json:"results"`
	}
	if err := json.Unmarshal([]byte(r.out), &res); err != nil {
		t.Fatal(err)
	}
	got := make([]string, len(res.Results))
	for i, x := range res.Results {
		got[i] = x.Status
	}
	want := []string{"settled", "settled", "limit_exceeded", "settled"}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("statuses=%v want %v", got, want)
	}
	for _, frag := range []string{"max_charged 1000", "used 1000", "charges 1"} {
		if !strings.Contains(res.Results[2].Reason, frag) {
			t.Fatalf("limit reason %q missing %q", res.Results[2].Reason, frag)
		}
	}

	// 上限仅对本次提交有效：下一批次从零计算，可再扣 1000。
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":0,
	  "limits":[{"account":"aa-1","asset":"usdc","max_charged":1000}],
	  "intents":[{"id":"p5","account":"aa-1","asset":"usdc","amount":900}]}`)
	if r.code != 0 || !strings.Contains(r.out, `"settled"`) {
		t.Fatalf("limit must reset per submission: code=%d out=%s err=%s", r.code, r.out, r.err)
	}

	// 非法限额：整个批次拒绝，退出码 1，invalid_parameter，任何意图都不执行。
	badLimits := []string{
		`{"fee_bps":0,"limits":[{"account":"","asset":"usdc","max_charged":1}],"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc"}],"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc","max_charged":null}],"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc","max_charged":-1}],"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc","max_charged":1.5}],"intents":[]}`,
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"usdc","max_charged":1},{"account":"aa-1","asset":"usdc","max_charged":2}],"intents":[]}`,
		// 空意图列表也要检查限额。
		`{"fee_bps":0,"limits":[{"account":"aa-1","asset":"","max_charged":1}],"intents":[]}`,
	}
	for _, bad := range badLimits {
		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, bad)
		if r.code != 1 || decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
			t.Fatalf("bad limits %s: code=%d err=%s", bad, r.code, r.err)
		}
	}
	// 带意图的非法限额批次同样整批拒绝。
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":0,
	  "limits":[{"account":"aa-1","asset":"usdc","max_charged":-1}],
	  "intents":[{"id":"p6","account":"aa-1","asset":"usdc","amount":1}]}`)
	if r.code != 1 {
		t.Fatalf("bad limits with intents: code=%d", r.code)
	}

	// 非法批次没有执行任何意图：余额与记录只来自前两次成功提交。
	r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
	if r.code != 0 {
		t.Fatalf("query code=%d", r.code)
	}
	var snap struct {
		Balances []struct {
			Account string `json:"account"`
			Asset   string `json:"asset"`
			Balance int64  `json:"balance"`
		} `json:"balances"`
		Settlements []struct {
			ID string `json:"id"`
		} `json:"settlements"`
	}
	if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
		t.Fatal(err)
	}
	if len(snap.Settlements) != 4 {
		t.Fatalf("settlements=%+v want 4 (p1, p2, p4, p5)", snap.Settlements)
	}
	if snap.Balances[0].Balance != 50 || snap.Balances[1].Balance != 100 {
		t.Fatalf("balances=%+v want usdc 50, eth 100", snap.Balances)
	}
}

package payflow

import (
	"fmt"
	"math"
)

// 付款数值约束的唯一维护处：金额、费率、手续费与扣款总额的规则只在
// 这里定义。本地结算（Submit/Preview 共用的 judgeIntent/validateBatch）、
// 遗留单笔结算（Execute）与账本历史校验（validateAndReplay）都从这里
// 取判定结果，再按各自入口对外的错误约定报告（invalid_parameter /
// rejected / corrupt_ledger），因此三处的数值语义始终一致。
//
// 规则：金额必须为正 int64；费率为 0 至 10000 基点；手续费按
// amount*feeBps/10000 向下取整；扣款总额为金额加手续费，总额必须
// 可表示为 int64。

// maxFeeBps 是费率上界（基点）：0 表示不收手续费，10000 表示手续费
// 等于付款金额。
const maxFeeBps = 10000

// amountValid 报告付款金额是否为正 int64。
func amountValid(amount int64) bool {
	return amount > 0
}

// feeBpsValid 报告费率是否在 [0, maxFeeBps] 基点内。
func feeBpsValid(feeBps int) bool {
	return feeBps >= 0 && feeBps <= maxFeeBps
}

// reasonBadFeeBps 是费率越界的统一说明，本地批次与遗留单笔共用同一措辞。
func reasonBadFeeBps(feeBps int) string {
	return fmt.Sprintf("fee_bps must be within [0,10000], got %d", feeBps)
}

// feeFor 计算手续费：amount*feeBps/10000 向下取整。
// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
// 拆成商和余数两部分即可在 int64 内精确完成。
func feeFor(amount int64, feeBps int) int64 {
	hi := amount / 10000
	lo := amount % 10000
	return hi*int64(feeBps) + (lo*int64(feeBps))/10000
}

// chargeFor 计算一笔付款的手续费与扣款总额（金额 + 手续费）。
// 前提：amount 与 feeBps 已分别通过 amountValid 与 feeBpsValid。
// 乘法中间结果不会溢出（见 feeFor），因此大额付款按精确金额判断；
// 只有最终总额超出 int64 时 ok 为 false（此时 fee 仍是精确值，
// total 无意义），调用方按各自约定把总额溢出报告为参数错误、
// 拒绝或账本损坏。
func chargeFor(amount int64, feeBps int) (fee, total int64, ok bool) {
	fee = feeFor(amount, feeBps)
	if fee > math.MaxInt64-amount {
		return fee, 0, false
	}
	return fee, amount + fee, true
}

