1	package payflow
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"math"
9		"os"
10		"path/filepath"
11		"syscall"
12	)
13	
14	// 账本文件的保存规则集中在 saveLedger 一处：序列化 → 同目录临时文件 →
15	// fsync → 0600 → 发布 → 目录 fsync。新建账本与更新已有账本只差最后的
16	// 发布策略（publishFunc）：
17	//   - 更新已有账本用 rename 原子替换（publishReplace）；
18	//   - 新建账本用 link(2) 排他创建（publishExclusive），目标被占用即拒绝。
19	//
20	// 关键不变式：磁盘上的目标文件在任意时刻要么是完整旧内容，要么是完整
21	// 新内容（临时文件先 fsync 后发布，JSON 只写一个文档）。进程在保存期间
22	// 崩溃，重开只能看到完整的旧状态或新状态，不会出现“扣款无记录”或
23	// “记录未扣款”。
24	//
25	// 发布之前任一步失败都会清理临时文件，目标位置不留半成品；发布一旦
26	// 完成，新状态已就位，后续目录 fsync 仅尽力而为，失败不再回滚。
27	
28	// publishFunc 把已完整落盘、已 fsync 的临时文件 tmp 发布到目标 path。
29	// 返回非 nil 表示发布失败，调用方负责清理临时文件。
30	type publishFunc func(tmp, path string) error
31	
32	// saveLedger 按统一的保存规则把 v 以 JSON 单文档保存到 path：
33	//  1. 写入同目录临时文件并 fsync（stageTempFile）；
34	//  2. 由 publish 把临时文件发布到目标位置；
35	//  3. 尽力 fsync 目录，帮助发布结果跨掉电保留。
36	//
37	// 发布失败时临时文件由这里统一清理；发布成功后临时名字也已统一移除
38	// （rename 后该名字本就不存在，link 后它是同一 inode 的多余名字）。
39	func saveLedger(path string, v any, publish publishFunc) error {
40		tmpName, err := stageTempFile(path, v)
41		if err != nil {
42			return err
43		}
44		if err := publish(tmpName, path); err != nil {
45			_ = os.Remove(tmpName)
46			return err
47		}
48		_ = os.Remove(tmpName)
49		syncParentDir(path)
50		return nil
51	}
52	
53	// stageTempFile 把 v 序列化为单个 JSON 文档，完整写入 path 同目录的
54	// 临时文件，fsync 后调整为 0600（仅所有者可读写），返回临时文件路径。
55	// 此时目标位置尚未被触碰；任一步失败都清理临时文件并返回 ErrStorage。
56	func stageTempFile(path string, v any) (string, error) {
57		data, err := json.Marshal(v)
58		if err != nil {
59			return "", ledgerError(ErrStorage, "encode ledger: %v", err)
60		}
61		data = append(data, '\n')
62	
63		dir := filepath.Dir(path)
64		if err := os.MkdirAll(dir, 0o700); err != nil {
65			return "", ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
66		}
67	
68		tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
69		if err != nil {
70			return "", ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
71		}
72		tmpName := tmp.Name()
73		removeTemp := func() { _ = os.Remove(tmpName) }
74	
75		if _, err := tmp.Write(data); err != nil {
76			_ = tmp.Close()
77			removeTemp()
78			return "", ledgerError(ErrStorage, "write temp file: %v", err)
79		}
80		if err := tmp.Sync(); err != nil {
81			_ = tmp.Close()
82			removeTemp()
83			return "", ledgerError(ErrStorage, "fsync temp file: %v", err)
84		}
85		if err := tmp.Close(); err != nil {
86			removeTemp()
87			return "", ledgerError(ErrStorage, "close temp file: %v", err)
88		}
89		if err := os.Chmod(tmpName, 0o600); err != nil {
90			removeTemp()
91			return "", ledgerError(ErrStorage, "chmod temp file: %v", err)
92		}
93		return tmpName, nil
94	}
95	
96	// syncParentDir 尽力 fsync path 的父目录，帮助已完成的发布跨掉电保留
97	// 目录项。发布完成后可能出现的两种结局（旧文件/新文件）都是完整状态，
98	// 因此这里失败不影响结果，调用方也不得因此回滚内存状态。
99	func syncParentDir(path string) {
100		if d, err := os.Open(filepath.Dir(path)); err == nil {
101			_ = d.Sync()
102			_ = d.Close()
103		}
104	}
105	
106	// publishReplace 用 rename 把临时文件原子发布到 path：目标位置已有的
107	// 内容被整体替换，读者任意时刻只能看到完整的旧版本或完整新版本。
108	// 用于更新已有账本。
109	//
110	// rename 之后新文件已完整就位。即便此后目录 fsync 失败，也不能再回滚：
111	// 回滚内存会与磁盘（已是新状态）分叉。
112	func publishReplace(tmp, path string) error {
113		if err := os.Rename(tmp, path); err != nil {
114			return ledgerError(ErrStorage, "rename into place: %v", err)
115		}
116		return nil
117	}
118	
119	// publishExclusive 用 link(2)（ATOMIC_CREATE：目标存在即失败）把临时文件
120	// 排他发布到 path，绝不覆盖任何已有路径项。用于新建账本。
121	//
122	// 这使“检查路径是否占用”和“创建账本”成为内核里的同一个原子操作：
123	//   - 普通文件、目录、损坏或空文件：EEXIST，原内容逐字节不变；
124	//   - path 上是符号链接（无论其目标存在与否、指向文件还是目录）：
125	//     link 不跟随符号链接，一律 EEXIST，链接本身与其去向保持不变，
126	//     也不会顺着悬空链接把目标文件创建出来；
127	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时，目录项原本
128	//     不存在，创建照常成功。
129	//
130	// 多个进程同时初始化同一尚不存在的路径时，只有一个 link 成功；
131	// 失败者拿到 EEXIST 并清理自己的临时文件，不会触碰胜出者的文件。
132	// 由于发布用的是硬链接而非 rename，胜出者磁盘上的文件从发布那一刻起
133	// 就是已 fsync 的完整内容（临时文件与 path 指向同一个 inode），
134	// 崩溃后同样只可能看到“完整新账本”或“路径不存在”，没有半成品。
135	//
136	// path 占用时返回带 ErrExists 的账本错误；其余失败返回 ErrStorage。
137	func publishExclusive(tmp, path string) error {
138		if err := os.Link(tmp, path); err != nil {
139			if errors.Is(err, syscall.EEXIST) {
140				return ledgerError(ErrExists, "ledger already exists at %s", path)
141			}
142			return ledgerError(ErrStorage, "create ledger at %s: %v", path, err)
143		}
144		return nil
145	}
146	
147	// atomicWrite 将 v 以 JSON 原子写入 path，替换该位置的已有账本。
148	// 保存规则见 saveLedger；发布策略是 rename 原子替换（publishReplace）。
149	func atomicWrite(path string, v any) error {
150		return saveLedger(path, v, publishReplace)
151	}
152	
153	// createExclusive 在 path 处排他地创建新账本文件，绝不覆盖任何已有路径项。
154	// 保存规则见 saveLedger；发布策略是 link(2) 排他创建（publishExclusive）：
155	// 路径占用返回 ErrExists 且原内容不变，写入故障返回 ErrStorage，
156	// 两种情况下路径上都不会留下半成品。
157	func createExclusive(path string, v any) error {
158		return saveLedger(path, v, publishExclusive)
159	}
160	
161	// validateAndReplay 校验全部成功记录并从冻结的初始余额重放结算与退款：
162	// ID 唯一、序列连续、费用一致、int64 不溢出、退款只能引用此前存在的结算且
163	// 每笔结算最多退回一次、退款金额必须等于原扣款、任一时点余额非负，
164	// 且重放结果必须等于文件中的最终余额。任何不符都判定账本损坏。
165	//
166	// 结算与退款按各自成功历史交错：退款 r 只允许发生在序号 <= r.AfterSeq 的
167	// 结算之后（AfterSeq 是退款落账时结算历史的长度）。这保留了
168	// “付款 → 退款 → 再付款”的真实时间顺序，使中间余额与最终余额都可验证。
169	func validateAndReplay(initial, final map[balanceKey]int64, records []Record, refunds []RefundRecord) error {
170		// 先校验结算自身的结构不变式（余额相关的判定由后面的交错重放完成，
171		// 因为退款回收的余额允许同一笔钱被再次扣出，累计毛扣款可能超过初始余额）。
172		seen := map[string]bool{}
173		for i, r := range records {
174			if r.ID == "" {
175				return ledgerError(ErrCorrupt, "settlement %d has empty id", i)
176			}
177			if seen[r.ID] {
178				return ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
179			}
180			seen[r.ID] = true
181			if r.Account == "" || r.Asset == "" {
182				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
183			}
184			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
185				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
186			}
187			if !amountValid(r.Amount) || r.Fee < 0 || r.Charged <= 0 {
188				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
189			}
190			if !feeBpsValid(r.FeeBps) {
191				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
192			}
193			// 手续费与扣款总额必须与统一数值规则（charge.go）逐字一致；
194			// 总额不可表示为 int64 时同样视为 charged 不符。
195			fee, total, ok := chargeFor(r.Amount, r.FeeBps)
196			if fee != r.Fee {
197				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, fee)
198			}
199			if !ok || r.Charged != total {
200				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
201			}
202			if int64(i)+1 != r.Seq {
203				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
204			}
205		}
206	
207		// 校验退款自身的不变式：字段非空、序列连续、引用的结算在退款时点已存在、
208		// 金额与去向与原结算逐字一致、每笔结算最多退回一次、退款编号全局唯一。
209		// 此外付款历史只会追加，因此按退款成功顺序（即记录顺序）看，after_seq
210		// 必须单调不减：后一笔退款落账时，已存在的结算不可能比前一笔退款时更少。
211		// 该规则针对整本账本的结算历史，与退款属于哪个账户、资产或引用哪笔付款无关。
212		seenRefund := map[string]bool{}
213		refundedBy := map[string]string{} // 结算编号 -> 首个退回它的退款编号
214		prevAfterSeq := int64(-1)
215		prevRefundID := ""
216		for i, rf := range refunds {
217			if rf.ID == "" {
218				return ledgerError(ErrCorrupt, "refund %d has empty id", i)
219			}
220			if seenRefund[rf.ID] {
221				return ledgerError(ErrCorrupt, "duplicate refund id %q", rf.ID)
222			}
223			seenRefund[rf.ID] = true
224			if rf.SettlementID == "" || rf.Reason == "" {
225				return ledgerError(ErrCorrupt, "refund %q missing settlement_id or reason", rf.ID)
226			}
227			if int64(i)+1 != rf.Seq {
228				return ledgerError(ErrCorrupt, "refund %q sequence gap", rf.ID)
229			}
230			if rf.AfterSeq < 0 || rf.AfterSeq > int64(len(records)) {
231				return ledgerError(ErrCorrupt, "refund %q references settlement outside history (after_seq=%d)", rf.ID, rf.AfterSeq)
232			}
233			if rf.AfterSeq < prevAfterSeq {
234				return ledgerError(ErrCorrupt,
235					"refund %q (seq %d) has after_seq %d, but previous refund %q (seq %d) already saw %d settlements: payment history only grows",
236					rf.ID, rf.Seq, rf.AfterSeq, prevRefundID, int64(i), prevAfterSeq)
237			}
238			prevAfterSeq = rf.AfterSeq
239			prevRefundID = rf.ID
240			var target *Record
241			for j := range records {
242				if records[j].Seq <= rf.AfterSeq && records[j].ID == rf.SettlementID {
243					target = &records[j]
244					break
245				}
246			}
247			if target == nil {
248				return ledgerError(ErrCorrupt, "refund %q references non-existent settlement %q", rf.ID, rf.SettlementID)
249			}
250			if rf.Account != target.Account || rf.Asset != target.Asset ||
251				rf.Amount != target.Amount || rf.Fee != target.Fee || rf.Charged != target.Charged {
252				return ledgerError(ErrCorrupt, "refund %q amount or destination differs from settlement %q", rf.ID, rf.SettlementID)
253			}
254			if rf.Charged <= 0 {
255				return ledgerError(ErrCorrupt, "refund %q has non-positive charged amount", rf.ID)
256			}
257			if other, dup := refundedBy[rf.SettlementID]; dup {
258				return ledgerError(ErrCorrupt, "settlement %q refunded twice: %q and %q", rf.SettlementID, other, rf.ID)
259			}
260			refundedBy[rf.SettlementID] = rf.ID
261		}
262	
263		// 按成功时间交错重放：第 s 笔结算之后落入 after_seq==s 的全部退款
264		// （退款之间按其自身序号；用分桶而非假定 after_seq 单调，以抵抗篡改数据）。
265		// net[k] 为该组合截至当前时点的“净扣款”（扣款增加、退款减少），
266		// 必须始终落在 [0, initial]，且不发生 int64 溢出。
267		buckets := make([][]int, len(records)+1) // after_seq -> refunds 下标
268		for i := range refunds {
269			buckets[refunds[i].AfterSeq] = append(buckets[refunds[i].AfterSeq], i)
270		}
271		net := make(map[balanceKey]int64)
272		for s := range records {
273			r := &records[s]
274			k := balanceKey{r.Account, r.Asset}
275			sum := net[k]
276			if r.Charged > math.MaxInt64-sum {
277				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
278			}
279			sum += r.Charged
280			if sum > initial[k] {
281				return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative during replay", r.ID, r.Account, r.Asset)
282			}
283			net[k] = sum
284	
285			for _, ri := range buckets[int64(s)+1] {
286				rf := &refunds[ri]
287				rk := balanceKey{rf.Account, rf.Asset}
288				cur := net[rk]
289				if rf.Charged > cur {
290					return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
291				}
292				net[rk] = cur - rf.Charged
293			}
294		}
295		// after_seq==0 的退款不可能引用任何已存在结算，前面理应已拒绝；
296		// 此处兜底，任何未被消费的退款都视为顺序损坏。
297		if len(buckets[0]) != 0 {
298			return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
299		}
300	
301		// 交错重放后的末态必须与文件中的最终余额逐组合一致。
302		for k, start := range initial {
303			got := start - net[k]
304			if want, present := final[k]; !present || got != want {
305				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
306			}
307		}
308		for k := range final {
309			if _, ok := initial[k]; !ok {
310				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
311			}
312		}
313		return nil
314	}
315	
316	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
317	func checksumHex(data []byte) string {
318		sum := sha256.Sum256(data)
319		return hex.EncodeToString(sum[:])
320	}
